/* @component: tab-hover-horisontal */
(function () {
  if (window.__tabHorizontalInit) return;
  window.__tabHorizontalInit = true;

  var closeTimers = new Map();

  function scheduleClose(pane, btn, delay) {
    if (closeTimers.has(pane)) clearTimeout(closeTimers.get(pane));
    var timer = setTimeout(function () {
      if (btn) btn.classList.remove('_is-active');
      closePane(pane);
      closeTimers.delete(pane);
    }, delay || 200);
    closeTimers.set(pane, timer);
  }

  function cancelClose(pane) {
    if (closeTimers.has(pane)) {
      clearTimeout(closeTimers.get(pane));
      closeTimers.delete(pane);
    }
  }

  function cancelCloseHierarchy(tab) {
    var current = tab;
    while (current) {
      var pane = current.querySelector('.tab-hover-content-horisontal');
      if (pane && pane.closest('.tab-hover-horisontal') === current) {
        cancelClose(pane);
      }
      current = current.parentElement ? current.parentElement.closest('.tab-hover-horisontal') : null;
    }
  }

  function prepPane(pane) {
    pane.style.overflow = 'hidden';
    pane.style.boxSizing = 'border-box';
    pane.style.transition = 'width 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.25s ease';
  }

  function getTargetWidth(pane) {
    var inner = pane.querySelector('.tab-hover-content-inner');
    if (inner && inner.closest('.tab-hover-content-horisontal') === pane) {
      var cs = window.getComputedStyle(pane);
      var borderW = (parseFloat(cs.borderLeftWidth) || 0) + (parseFloat(cs.borderRightWidth) || 0);
      return Math.ceil(inner.getBoundingClientRect().width + borderW);
    }
    var prevWidth = pane.style.width;
    pane.style.width = 'max-content';
    var target = Math.ceil(pane.getBoundingClientRect().width);
    pane.style.width = prevWidth;
    return target;
  }

  function initPanes() {
    document.querySelectorAll('.tab-hover-horisontal .tab-hover-content-horisontal').forEach(function (pane) {
      if (pane.dataset.tabHInit === 'true') return;
      pane.dataset.tabHInit = 'true';
      prepPane(pane);
      if (pane.classList.contains('_is-active')) {
        pane.style.width = 'max-content';
        pane.style.opacity = '1';
        pane.style.pointerEvents = 'auto';
        pane.style.overflow = 'visible';
      } else {
        pane.style.width = '0px';
        pane.style.opacity = '0';
        pane.style.pointerEvents = 'none';
        pane.style.overflow = 'hidden';
      }
    });
  }

  function openPane(pane) {
    cancelClose(pane);
    prepPane(pane);
    var start = pane.offsetWidth;
    pane.style.overflow = 'hidden';
    pane.style.width = start + 'px';
    pane.classList.add('_is-active');
    pane.style.pointerEvents = 'auto';

    var target = getTargetWidth(pane);
    pane.style.opacity = start === 0 ? '0' : '1';

    pane.offsetWidth;

    pane.style.opacity = '1';
    if (start === target && target > 0) {
      pane.style.width = 'max-content';
      pane.style.overflow = 'visible';
    } else {
      pane.style.width = target + 'px';
    }
  }

  function closePane(pane) {
    pane.querySelectorAll('.btn-tab-hover._is-active').forEach(function (b) {
      b.classList.remove('_is-active');
    });
    pane.querySelectorAll('.tab-hover-content-horisontal._is-active').forEach(function (p) {
      closePane(p);
    });

    pane.style.overflow = 'hidden';
    pane.style.pointerEvents = 'none';

    var start = pane.scrollWidth || pane.offsetWidth;
    pane.style.transition = 'none';
    pane.style.width = start + 'px';
    pane.style.opacity = '1';

    pane.offsetWidth;

    pane.style.transition = 'width 0.28s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.22s ease';
    pane.classList.remove('_is-active');
    pane.style.opacity = '0';
    pane.style.width = '0px';
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initPanes);
  } else {
    initPanes();
  }
  setTimeout(initPanes, 300);

  document.addEventListener('transitionend', function (e) {
    if (e.propertyName === 'width' && e.target.classList.contains('tab-hover-content-horisontal')) {
      var pane = e.target;
      if (pane.classList.contains('_is-active')) {
        pane.style.width = 'max-content';
        pane.style.overflow = 'visible';
      }
    }
  });

  document.addEventListener('mouseover', function (e) {
    var tab = e.target.closest('.tab-hover-horisontal');
    if (!tab) return;

    cancelCloseHierarchy(tab);

    var btn = tab.querySelector('.btn-tab-hover');
    var pane = tab.querySelector('.tab-hover-content-horisontal');
    if (btn && pane && btn.closest('.tab-hover-horisontal') === tab && pane.closest('.tab-hover-horisontal') === tab) {
      btn.classList.add('_is-active');
      openPane(pane);
    }
  });

  document.addEventListener('mouseout', function (e) {
    var tab = e.target.closest('.tab-hover-horisontal');
    if (!tab) return;

    if (!e.relatedTarget || !tab.contains(e.relatedTarget)) {
      var btn = tab.querySelector('.btn-tab-hover');
      var pane = tab.querySelector('.tab-hover-content-horisontal');
      if (btn && pane && btn.closest('.tab-hover-horisontal') === tab && pane.closest('.tab-hover-horisontal') === tab) {
        scheduleClose(pane, btn, 200);
      }
    }
  });

  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.btn-tab-hover');
    if (!btn) return;
    var tab = btn.closest('.tab-hover-horisontal');
    if (!tab) return;
    var pane = tab.querySelector('.tab-hover-content-horisontal');
    if (!pane || pane.closest('.tab-hover-horisontal') !== tab) return;

    cancelClose(pane);
    if (btn.classList.contains('_is-active')) {
      btn.classList.remove('_is-active');
      closePane(pane);
    } else {
      btn.classList.add('_is-active');
      openPane(pane);
    }
  });
})();
/* @end: tab-hover-horisontal */
